package com.elektoryk.scan.storage;
import android.content.Context;import com.elektoryk.scan.model.*;import org.json.JSONObject;import java.io.File;
public class CatalogRepository {private final File file;public CatalogRepository(Context c){File d=new File(c.getFilesDir(),"catalog");if(!d.exists())d.mkdirs();file=new File(d,"catalog.json");}public synchronized CatalogState load(){if(!file.exists())return new CatalogState();try{return CatalogState.fromJson(new JSONObject(AtomicFileStore.readText(file)));}catch(Exception e){File b=new File(file.getParentFile(),file.getName()+".bak");if(b.exists())try{CatalogState s=CatalogState.fromJson(new JSONObject(AtomicFileStore.readText(b)));AtomicFileStore.restoreBackup(file);return s;}catch(Exception ignored){}return new CatalogState();}}public synchronized void save(CatalogState s){try{AtomicFileStore.writeText(file,s.toJson().toString(2));}catch(Exception e){throw new RuntimeException(e);}}public synchronized void updateFrom(CommercialLine l){if(l==null||l.stableKey.isEmpty())return;CatalogState s=load();CatalogItem i=s.find(l.stableKey);if(i==null){i=new CatalogItem();i.stableKey=l.stableKey;s.items.add(i);}i.name=l.name;i.unit=l.unit;i.unitCost=l.unitCost;i.packSize=l.packSize;i.stockQty=l.stockQty;i.updatedAt=System.currentTimeMillis();save(s);}}
